+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @SuppressWarnings("unchecked")
+    private Grid<ai.unifiedprocess.petclinic.vet.domain.Vet> grid() {
+        navigate(VetsView.class);
+        return find(Grid.class).single();
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-001", "BR-003"})
+    void gridListsAllVetsWithoutLogin() {
+        var grid = grid();
+        assertEquals(6, grid.getDataProvider().size(new Query<>()));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreSortedAlphabeticallyAndNoneIsShown() {
+        var vets = grid().getDataProvider().fetch(new Query<>()).toList();
+        var carter = vets.stream().filter(v -> v.lastName().equals("Carter")).findFirst().orElseThrow();
+        var douglas = vets.stream().filter(v -> v.lastName().equals("Douglas")).findFirst().orElseThrow();
+        assertEquals(List.of(), carter.specialties());
+        assertEquals(List.of("dentistry", "surgery"), douglas.specialties());
+        assertEquals("none", test(grid()).getCellText(0, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridFetchesInChunks() {
+        var provider = grid().getDataProvider();
+        assertEquals(2, provider.fetch(new Query<>(2, 2, null, null, null)).count());
+    }
+}
